import {chains,restaurantName,restaurantFoods} from './restaurants.mjs';
let restaurantFilter='';
import {rankFoods} from './search.mjs';
import {avatar,poses,storageKey,diaryCsv,periodRows,safeLink} from './gamna.mjs';
import {createFirebaseSession} from './firebase-session.mjs';
import {recipeNutrition} from './indian.mjs';
import {personalCatalog,matchesFood} from './personal.mjs';
import {keys,scale,totals,localDate,weightTrend,averageWeight} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({version:1,days:{},customFoods:[],recipes:[],profile:{name:'You',diet:'vegetarian',goal:'Build strength & lose fat',targets:{kcal:2100,protein:95,fat:65,carbs:250,fiber:30,sleep:8,exercise:30}},revision:0,pending:true});
let legacyEligible=false;
let state=blank(),profilePhoto=null,pose=0,sessionEpoch=0,sessionReady=false,progressMetric='weight',progressRange=28,foodCategory='all';
const saveLocal=()=>{if(cloudUser)localStorage.setItem(storageKey(cloudUser.uid),JSON.stringify(state));};
let authSession=null,authLoad=null;
let syncRetries=0,syncing=false,syncTimer,personal={favorites:[],extras:[],combos:[]},tray=[],trayMeal="Breakfast",foodLimit=18;
let foods=[],tab='today',date=localDate(),search='',filter=state.profile.diet,cloudUser=null,recipeDraft=[],recipeMeta={},storageAvailable=true;
const names={kcal:'Calories',protein:'Protein',fat:'Fat',carbs:'Carbs',fiber:'Fiber'};
const colors={protein:'#9bc779',fat:'#eac06a',carbs:'#94b2d6',fiber:'#c0a3d6',kcal:'#91ad68'};
const day=()=>state.days[date]||{meals:[],weight:null,sleep:null,exercise:[]};
const exerciseMinutes=d=>(d.exercise||[]).reduce((s,e)=>s+e.minutes,0);
const n=v=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:1});
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function persist(){if(!cloudUser||!sessionReady)return;state.pending=true;state.eventId=crypto.randomUUID();try{saveLocal();storageAvailable=true;}catch{storageAvailable=false;notify('Device storage is unavailable. Export CSV to keep your entries.');}updateStatus();if(cloudUser){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}
function updateStatus(){$('#save-status').textContent=!storageAvailable?'Not saved — export CSV':state.pending?'Saving your diary…':'All changes saved';}
function editDay(fn){pose=(pose+1)%12;const d=structuredClone(day());fn(d);state.days[date]=d;persist();render();}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function close(){$('#modal').close();}
$('.close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close();});
$('#day').value=date;$('#day').max=localDate();$('#day').onchange=e=>{if(e.target.value&&e.target.value<=localDate()){date=e.target.value;render();}};
function navigate(t){tab=t;pose=(pose+1)%12;render();}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));$('#profile-button').onclick=()=>navigate('profile');
function render(){if(!cloudUser||!sessionReady)return;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#date-label').textContent=new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#page-title').innerHTML=({today:'Make today count',food:'What sounds good?',progress:'Look how far you’ve come',settings:'Make it yours',training:'Move your way',profile:'A little more you'}[tab])+'<span>.</span>';$('#profile-button').textContent=state.profile.name.slice(0,1);({today:renderToday,food:renderFood,progress:renderProgress,settings:renderSettings,training:renderTraining,profile:renderProfile}[tab])();updateStatus();attachDepth();}
function renderToday(){const d=day(),t=totals(d.meals),g=state.profile.targets,min=exerciseMinutes(d),trend=weightTrend(state.days,date);const quests=[{done:d.meals.length>0,title:'Fuel your day',detail:'Log a meal, however simple.',action:'food'},{done:d.weight!=null,title:'Check in with yourself',detail:'A weight entry is a data point, not a verdict.',action:'weight'},{done:min>=g.exercise,title:'Find your kind of movement',detail:`${n(min)} / ${g.exercise} minutes logged`,action:'exercise'}];const count=quests.filter(q=>q.done).length;
$('#content').innerHTML=`<div class="top-grid"><section class="journey mission-scene" id="mission-scene"><div class="journey-copy"><span class="pill">YOUR EVERYDAY CHAPTER</span><h2>Build strength.<br>Find your rhythm.</h2><p>Good food. Movement you enjoy.<br>A little more you, every week.</p><button class="primary" id="log-meal">+ Fuel up</button><button class="text-button" id="open-training">Explore activity</button></div><div class="avatar-space"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><button class="identity-core personal-avatar" id="avatar-info" aria-label="Open your personal avatar">${avatar(pose,profilePhoto,state.profile.skin,state.profile.hair)}</button><span class="orbit-data protein-orbit">${n(t.protein)}<small>g protein</small></span><span class="orbit-data movement-orbit">${min}<small>min moved</small></span></div><span class="scene-caption">Tap your companion for a little lift</span></section><section class="card"><div class="card-head"><h2>Daily energy</h2><small>kcal</small></div><div class="energy-body"><div class="ring" style="--angle:${Math.min(360,t.kcal/g.kcal*360)}deg"><div class="ring-text"><strong>${n(t.kcal)}</strong><small>of ${n(g.kcal)} kcal</small></div></div><div class="energy-details"><p>${t.kcal>g.kcal?'ABOVE TARGET':'REMAINING'}</p><b>${n(Math.abs(g.kcal-t.kcal))} <small>kcal</small></b><hr><p>MEALS LOGGED</p><b>${d.meals.length}</b></div></div><p class="hint">${t.missing.includes('kcal')?'Some foods are missing energy values. Total is partial.':(d.meals.some(m=>m.food?.estimated)?'Includes your earlier recipe estimates.':'Your editable target · exercise calories are not deducted.')}</p></section></div><div class="section-heading"><h2>Your daily essentials</h2><button class="text-button" id="edit-targets">Edit targets</button></div><div class="macros">${['protein','carbs','fat','fiber'].map(k=>`<div class="macro"><div class="macro-top"><span>${names[k]}</span><span style="color:${colors[k]}">◈</span></div><strong>${n(t[k])}<small> g</small></strong> <small>/ ${g[k]} g${t.missing.includes(k)?' · partial':''}</small><div class="bar"><span style="width:${Math.min(100,t[k]/g[k]*100)}%;--color:${colors[k]}"></span></div></div>`).join('')}<div class="macro"><div class="macro-top"><span>Movement</span><span>↗</span></div><strong>${n(min)}<small> min</small></strong> <small>/ ${g.exercise}</small><div class="bar"><span style="width:${Math.min(100,min/g.exercise*100)}%"></span></div></div></div><div class="checkins"><button class="checkin" data-check="weight"><span>◉ &nbsp; BODY WEIGHT</span><strong>${d.weight==null?'Add weight':n(d.weight)+' kg'}</strong><small>${trend&&trend.to===date?`${Math.abs(trend.delta)<0.05?'Steady':trend.delta>0?'↑ Gained':'↓ Lost'} ${n(Math.abs(trend.delta))} kg since ${trend.from}`:'Build your personal baseline'} · +</small></button><button class="checkin" data-check="sleep"><span>☾ &nbsp; LAST NIGHT’S SLEEP</span><strong>${d.sleep==null?'Log sleep':n(d.sleep)+' hours'}</strong><small>Your target: ${g.sleep} hours · +</small></button><button class="checkin" data-check="exercise"><span>↗ &nbsp; EXERCISE</span><strong>${min?min+' minutes':'Add movement'}</strong><small>Every kind of movement counts · +</small></button></div><div class="lower-grid"><section class="card"><div class="card-head"><h2>On your plate</h2><button class="text-button" id="add-food">+ Add food</button></div>${d.meals.length?d.meals.map((m,i)=>`<div class="meal-row"><span class="meal-icon">◈</span><div class="meal-info"><b>${esc(m.name)}</b><small>${esc(m.meal)} · ${n(m.grams)} g · ${m.nutrients.protein==null?"—":n(m.nutrients.protein)} g protein</small></div><span class="meal-kcal">${m.nutrients.kcal==null?'—':n(m.nutrients.kcal)}</span><button class="text-button" data-edit="${i}" aria-label="Edit ${esc(m.name)}">Edit</button><button class="text-button danger" data-delete="${i}" aria-label="Delete ${esc(m.name)}">×</button></div>`).join(''):`<div class="meal-empty"><div class="empty-symbol">◈</div><h3>A fresh plate. A fresh start.</h3><p>Find your food, dial in the portion,<br>and let the numbers take care of themselves.</p><button class="secondary" id="browse-food">Explore food studio</button></div>`}</section><section class="card"><div class="card-head"><h2>Today’s little wins</h2><span class="tag">${count}/3 complete</span></div>${quests.map(q=>`<div class="quest ${q.done?'complete':''}"><span class="quest-icon">${q.done?'✓':'○'}</span><div><b>${q.title}</b><p>${q.detail}</p></div><button class="text-button" data-quest="${q.action}">${q.done?'Edit':'Start'}</button></div>`).join('')}</section></div><div class="insight"><span>✦</span><div><b>A thought for today</b><p>${suggestion(d,t)}</p></div></div><footer>Your goals, your pace. Review longer trends rather than judging a single day.</footer>`;
['#log-meal','#add-food','#browse-food'].forEach(s=>{if($(s))$(s).onclick=()=>navigate('food');});$('#open-training').onclick=()=>navigate('training');$('#avatar-info').onclick=()=>{pose=(pose+1)%12;render();notify(poses[pose]);};$('#edit-targets').onclick=()=>navigate('settings');document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>checkin(b.dataset.check));document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>b.dataset.quest==='food'?navigate('food'):checkin(b.dataset.quest));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Remove this food from this day?'))editDay(d=>d.meals.splice(Number(b.dataset.delete),1));});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>portion(day().meals[Number(b.dataset.edit)].food,Number(b.dataset.edit)));}
function suggestion(d,t){if(!d.meals.length)return 'Start by logging what you normally eat. A useful pattern begins with an honest picture of your day.';if(t.missing.length)return 'Some foods have missing nutrient values. Check their labels before drawing conclusions from today’s totals.';if(t.protein<state.profile.targets.protein*.6)return 'Your logged protein is below your chosen target so far. Explore lentils, tofu, beans or plain Greek yogurt for your next meal.';if(d.sleep==null)return 'Add last night’s sleep to put your food and activity in context. Look for patterns across weeks, not one day.';return 'You’re building a useful record. Compare weekly averages and how you feel before changing your routine.';}
function checkin(type){if(type==='exercise'){modal(`<h2>Move in your own way</h2><p>A walk, a workout, a stretch. It all belongs here.</p><form id="check-form"><label class="field">Activity<select name="activity"><option>Strength training</option><option>Walking</option><option>Running</option><option>Cycling</option><option>Yoga</option><option>Swimming</option><option>Other exercise</option></select></label><label class="field">Minutes<input name="value" type="number" min="1" max="1440" required></label><button class="primary">Save activity</button></form>${day().exercise.map((e,i)=>`<div class="meal-row"><div class="meal-info">${esc(e.name)} · ${e.minutes} min</div><button class="text-button danger" data-remove-ex="${i}">Remove</button></div>`).join('')}`);document.querySelectorAll('[data-remove-ex]').forEach(b=>b.onclick=()=>{editDay(d=>d.exercise.splice(+b.dataset.removeEx,1));close();checkin(type);});}else{modal(`<h2>${type==='weight'?'Your daily check-in':'Rest is part of the work'}</h2><p>${type==='weight'?'A single reading can fluctuate. Your longer trend matters.':'Sleep duration for the night ending on the selected day.'}</p><form id="check-form"><label class="field">${type==='weight'?'Weight (kg)':'Sleep (hours)'}<input name="value" type="number" step="0.1" min="${type==='weight'?20:0}" max="${type==='weight'?400:24}" value="${day()[type]??''}" required></label><button class="primary">Save check-in</button></form>`);}$('#check-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Number(f.get('value'));editDay(d=>{if(type==='exercise')d.exercise.push({id:crypto.randomUUID(),name:f.get('activity'),minutes:v,source:'manual'});else d[type]=v;});close();notify('One small win, saved.');};}
function allFoods(){return [...state.customFoods,...state.recipes,...personal.extras,...restaurantFoods,...foods];}
function foodVisual(f){return typeof f.image==='string'&&((f.image.startsWith('assets/')&&!f.image.includes('..'))||/^https:\/\/images\.openfoodfacts\.org\//.test(f.image))?`<img src="${esc(f.image)}" alt="${esc(f.displayName||f.name)}" loading="lazy">`:`<span class="food-symbol" aria-hidden="true">${esc(f.emoji||(/rice/i.test(f.name)?'🍚':/milk|yogurt|cheese/i.test(f.name)?'🥛':/banana|fruit/i.test(f.name)?'🍌':/lentil|bean|chickpea/i.test(f.name)?'🫘':'🥗'))}</span>`;}
function renderFood(){const searching=search.trim().length>0;const catalog=[...personal.favorites,...state.customFoods,...state.recipes,...allFoods()];const seen=new Set();const unique=catalog.filter(f=>{if(!f.id||seen.has(f.id))return false;seen.add(f.id);return true;});const matches=unique.filter(f=>(filter==='all'||filter==='vegetarian'&&['plant','dairy'].includes(f.diet)||f.diet===filter||filter==='custom'&&(state.customFoods.some(x=>x.id===f.id)||state.recipes.some(x=>x.id===f.id)))&&matchesFood(f,search));const categorized=rankFoods(matches.filter(f=>(!restaurantFilter||restaurantName(f)===restaurantFilter)&&(foodCategory==='all'||foodGroup(f)===foodCategory)),search,state.days,date);const shown=categorized.slice(0,foodLimit);
$('#content').innerHTML=`<div class="food-workspace"><div class="food-shelf"><div class="search-dock"><span>⌕</span><input type="search" id="search" autocomplete="off" placeholder="Try “Chobani yogurt” or “rice”…" value="${esc(search)}" aria-label="Search foods"><button class="text-button" id="custom">+ Custom</button></div><div class="filter-chips" role="group" aria-label="Food filters">${[['vegetarian','Vegetarian'],['plant','Plant-based'],['all','All foods'],['custom','My recipes & foods']].map(([v,l])=>`<button class="${filter===v?'selected':''}" data-filter="${v}">${l}</button>`).join('')}</div>${!searching&&filter==='vegetarian'?`<div class="section-heading"><div><span class="eyebrow">LESS TAPPING. MORE LIVING.</span><h2>Your go-to combinations</h2></div><button class="text-button" id="recipe">Build a recipe</button></div><div class="combo-row">${personal.combos.map(c=>`<button class="combo-card" data-combo="${c.id}">${foodVisual(c)}<span class="combo-shade"></span><span class="combo-copy"><small>${c.estimated?'INCLUDES ESTIMATES':'INGREDIENT-BASED'}</small><b>${c.name}</b><span>${c.description}</span></span><span class="combo-add">+</span></button>`).join('')}</div>`:''}<div class="category-chips" aria-label="Food categories">${['all','Indian dishes','Grains','Pulses & protein','Dairy','Vegetables','Fruit','Fats & oils','Other'].map(c=>`<button data-category="${c}" class="${foodCategory===c?'selected':''}">${c==='all'?'Everything':c}</button>`).join('')}</div><label class="field">Restaurant<select id="restaurant-filter"><option value="">All foods & home cooking</option>${chains.map(([name])=>`<option value="${name}" ${restaurantFilter===name?'selected':''}>${name}</option>`).join('')}</select></label>${restaurantFilter?'<p class="notice">US menu library. Many records are historical USDA measurements (2018), not today’s menu labels. Check the source date before logging. Choose “All foods” above to include meat.</p>':''}<div class="shelf-actions"><button class="secondary" id="build-recipe">+ Build a recipe</button><button class="secondary" id="repeat-meal">Repeat a recent meal</button><button class="secondary" id="barcode">Find a packaged food</button></div><div class="section-heading"><h2>${searching?'Find your exact match':'Explore your food library'}</h2><span class="muted">${categorized.length.toLocaleString()} foods</span></div><div class="visual-food-grid">${shown.map(f=>{const grams=f.defaultGrams||100,t=scale(f.nutrients,grams);return `<article class="visual-food-card"><button class="food-front" data-explore="${esc(f.id)}">${foodVisual(f)}<span class="food-badge">${f.estimated?'ESTIMATE':f.id.startsWith('brand-')?'PRODUCT LABEL':'FOOD RECORD'}</span></button><div class="food-card-copy"><h3>${esc(f.displayName||f.name)}</h3><p>${n(grams)+' g'} · ${t.kcal==null?'—':n(t.kcal)} kcal</p><div class="food-card-bottom"><span><b>${t.protein==null?'—':n(t.protein)}g</b> protein</span><button class="round-add" data-tray="${esc(f.id)}" aria-label="Add ${esc(f.displayName||f.name)} to meal tray">+</button></div></div></article>`;}).join('')}</div>${!shown.length?'<div class="card meal-empty"><h3>Let’s add your version.</h3><p>No matching product yet. Use “Custom” to enter its label. Brands and flavors aren’t interchangeable.</p></div>':''}${categorized.length>foodLimit?'<button class="secondary full" id="more-foods">Show more matches</button>':''}<footer>Product photos identify exact items. Meal photos are illustrative. Recipe photos are AI illustrations. Modeled dishes are estimates; customize ingredients to match your cooking. Tap a card to inspect its source. <a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener">USDA library</a></footer></div><aside class="meal-tray" id="meal-tray"></aside></div>`;
$('#restaurant-filter').onchange=e=>{restaurantFilter=e.target.value;foodLimit=18;renderFood();};$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;foodLimit=18;renderFood();$('#search').focus();$('#search').setSelectionRange(pos,pos);};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;foodLimit=18;renderFood();});$('#custom').onclick=customFood;$('#build-recipe').onclick=()=>recipeBuilder();$('#repeat-meal').onclick=repeatMeal;$('#barcode').onclick=lookupBarcode;document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{foodCategory=b.dataset.category;foodLimit=18;renderFood();});if($('#recipe'))$('#recipe').onclick=()=>recipeBuilder();if($('#more-foods'))$('#more-foods').onclick=()=>{foodLimit+=18;renderFood();};const find=id=>unique.find(f=>String(f.id)===id);document.querySelectorAll('[data-tray]').forEach(b=>b.onclick=()=>{const f=find(b.dataset.tray);tray.push({food:structuredClone(f),grams:f.defaultGrams||100});renderTray();notify('Added to your meal tray. Review, then log.');});document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>portion(find(b.dataset.explore)));document.querySelectorAll('[data-combo]').forEach(b=>b.onclick=()=>{const combo=personal.combos.find(c=>c.id===b.dataset.combo);for(const [id,grams]of combo.items){const f=find(id);if(f)tray.push({food:structuredClone(f),grams});}renderTray();notify('Combination added. Adjust each portion before logging.');});renderTray();attachDepth();}
function renderTray(){if(!$('#meal-tray'))return;const t=totals(tray.filter(x=>Number.isFinite(x.grams)&&x.grams>0&&x.grams<=10000).map(x=>({nutrients:scale(x.food.nutrients,x.grams)})));$('#meal-tray').innerHTML=`<div class="tray-head"><span class="eyebrow">MEAL IN THE MAKING</span><h2>Your plate<span>.</span></h2><p>${tray.length?'Looking good. Make it your portion.':'Build a meal from your favorites.'}</p></div><div class="tray-orbit"><strong id="tray-energy">${n(t.kcal)}${t.missing.includes('kcal')?'*':''}</strong><small>kcal in this meal</small></div>${tray.length?`<div class="tray-items">${tray.map((x,i)=>`<div class="tray-item"><div class="tray-thumb">${foodVisual(x.food)}</div><div><b>${esc(x.food.displayName||x.food.name)}</b><label><input type="number" required min=".1" max="10000" step=".1" value="${Number.isFinite(x.grams)?x.grams:''}" data-grams="${i}" aria-label="Grams of ${esc(x.food.name)}"> g ${x.food.estimated?'· estimate':''}</label></div><button data-remove-tray="${i}" aria-label="Remove ${esc(x.food.name)}">×</button></div>`).join('')}</div>`:'<div class="tray-empty">Tap + on a food<br>or choose a combination.</div>'}<div class="tray-macros">${['protein','carbs','fat','fiber'].map(k=>`<div><b data-tray-total="${k}">${n(t[k])}g${t.missing.includes(k)?'*':''}</b><small>${names[k]}</small></div>`).join('')}</div><label class="field">Add to<select id="tray-meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><button class="primary full" id="log-tray" ${tray.length?'':'disabled'}>Log this meal · ${date}</button><p class="hint">${tray.some(x=>x.food.estimated)?'Includes recipe estimates. ':''}Nothing is logged until you tap this button.${t.missing.length?' * Partial totals.':''}</p>`;
updateTrayTotals();$('#tray-meal').value=trayMeal;$('#tray-meal').onchange=e=>{trayMeal=e.target.value;};document.querySelectorAll('[data-grams]').forEach(input=>input.oninput=e=>{tray[+e.target.dataset.grams].grams=e.target.valueAsNumber;updateTrayTotals();});document.querySelectorAll('[data-remove-tray]').forEach(b=>b.onclick=()=>{tray.splice(+b.dataset.removeTray,1);renderTray();});$('#log-tray').onclick=()=>{const invalid=$('#meal-tray input:invalid');if(invalid){invalid.reportValidity();return;}const meal=$('#tray-meal').value;editDay(d=>{for(const x of tray)d.meals.push({id:crypto.randomUUID(),foodId:x.food.id,name:x.food.displayName||x.food.name,grams:x.grams,meal,nutrients:scale(x.food.nutrients,x.grams),food:structuredClone(x.food)});});tray=[];renderFood();notify('Meal logged. Daily nutrition updated.');};}

function updateTrayTotals(){
 const valid=tray.length>0&&tray.every(x=>Number.isFinite(x.grams)&&x.grams>0&&x.grams<=10000)&&!$('#meal-tray input:invalid');
 $('#log-tray').disabled=!valid;
 const t=valid?totals(tray.map(x=>({nutrients:scale(x.food.nutrients,x.grams)}))):null;
 $('#tray-energy').textContent=t?n(t.kcal)+(t.missing.includes('kcal')?'*':''):'—';
 document.querySelectorAll('[data-tray-total]').forEach(el=>{const k=el.dataset.trayTotal;el.textContent=t?n(t[k])+'g'+(t.missing.includes(k)?'*':''):'—';});
}
function portion(food,index=null){const existing=index==null?null:day().meals[index];let grams=existing?.grams||food.defaultGrams||100;modal(`<span class="tag">${esc(food.source)}</span>${food.image?`<img class="portion-photo" src="${esc(food.image)}" alt="${esc(food.displayName||food.name)}">`:""}<h2>${esc(food.displayName||food.name)}</h2><p>${esc(food.note||"Choose the matching preparation and weigh your portion.")}</p>${food.ingredients?'<button class="secondary full" id="customize-recipe">Customize recipe · ingredients & oil</button>':''}<form id="portion-form"><label class="field">Serving size<select id="serving"><option value="">Custom grams</option><option value="100">100 g</option>${(food.portions||[]).map(p=>`<option value="${p.grams}">${esc(p.label)} (${n(p.grams)} g)</option>`).join('')}</select></label><label class="field">Quantity (grams)<div class="quantity"><button type="button" id="minus" aria-label="Reduce portion">−</button><input id="grams" type="number" min="0.1" max="10000" step="0.1" required value="${grams}"><button type="button" id="plus" aria-label="Increase portion">+</button></div></label><input id="quantity-range" aria-label="Adjust portion in grams" type="range" min="5" max="500" step="5" value="${grams}"><div class="nutrition-preview" id="nutrition-preview"></div><label class="field">Meal<select id="meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><p class="hint">${food.sourceUrl?`<a href="${esc(safeLink(food.sourceUrl))}" target="_blank" rel="noopener">View original nutrient record</a>`:'User-entered or recipe-calculated nutrition.'} · Values scale from 100 g. Missing values stay unknown.</p><button class="primary">${index==null?'Add to my day':'Save portion'}</button>${index==null?'<button type="button" id="add-ingredient" class="text-button full">Add to recipe instead</button>':''}</form>`);if($('#customize-recipe'))$('#customize-recipe').onclick=()=>recipeBuilder(food);if(existing)$('#meal').value=existing.meal;const preview=()=>{grams=Number($('#grams').value);if(!Number.isFinite(grams)||grams<=0||grams>10000){$('#nutrition-preview').textContent='Enter a valid portion to calculate nutrition.';return;}const t=scale(food.nutrients,grams);$('#nutrition-preview').innerHTML=keys.map(k=>`<span><b>${t[k]==null?'—':n(t[k])}${k==='kcal'?'':' g'}</b>${names[k]}</span>`).join('');$('#quantity-range').value=grams;$('#serving').value=String(grams);if(!$('#serving').value)$('#serving').value='';};$('#grams').oninput=preview;$('#quantity-range').oninput=e=>{$('#grams').value=e.target.value;preview();};$('#serving').value=String(grams);if(!$('#serving').value)$('#serving').value='';$('#serving').onchange=e=>{if(e.target.value){$('#grams').value=e.target.value;preview();}};$('#minus').onclick=()=>{$('#grams').value=Math.max(.1,grams-10);preview();};$('#plus').onclick=()=>{$('#grams').value=Math.min(10000,grams+10);preview();};preview();$('#portion-form').onsubmit=e=>{e.preventDefault();const entry={id:existing?.id||crypto.randomUUID(),foodId:food.id,name:food.name,grams,meal:$('#meal').value,nutrients:scale(food.nutrients,grams),food:structuredClone(food)};editDay(d=>{if(index==null)d.meals.push(entry);else d.meals[index]=entry;});close();notify('Meal saved. Your daily totals are updated.');};if($('#add-ingredient'))$('#add-ingredient').onclick=()=>{if(!$('#portion-form').reportValidity())return;recipeDraft.push({food,grams});close();recipeBuilder();};}
function customFood(){modal(`<h2>A place for your favorites</h2><p>Copy the nutrition label. Enter values per 100 g; leave unknown nutrients blank.</p><form id="custom-form" class="form-grid"><label class="field wide">Food name<input name="name" required maxlength="180"></label><label class="field wide">Diet<select name="diet"><option value="dairy">Vegetarian with dairy</option><option value="plant">Plant-based</option><option value="other">Other / unknown</option></select></label>${keys.map(k=>`<label class="field">${names[k]} ${k==='kcal'?'(kcal)':'(g)'}<input type="number" name="${k}" min="0" max="${k==='kcal'?1000:100}" step="0.01"></label>`).join('')}<label class="field wide">Label / source note<input name="note" maxlength="300" placeholder="Brand and product, package label"></label><button class="primary wide">Save custom food</button></form>`);$('#custom-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),food={id:'custom-'+crypto.randomUUID(),name:f.get('name').trim(),diet:f.get('diet'),source:'Your nutrition label',sourceNote:f.get('note'),basisGrams:100,portions:[],nutrients:Object.fromEntries(keys.map(k=>[k,f.get(k)===''?null:Number(f.get(k))]))};if(!food.name)return;state.customFoods.push(food);persist();close();renderFood();portion(food);};}
function recipeBuilder(template){
 if(template){recipeDraft=structuredClone(template.ingredients);recipeMeta={name:'My '+(template.displayName||template.name),weight:template.batchGrams||template.portions?.find(p=>p.label==='Full batch')?.grams||500,image:template.image};}
 const remember=()=>{recipeMeta.name=$('#recipe-name').value;recipeMeta.weight=$('#recipe-weight').value;};
 modal(`<h2>Your recipe, your portions</h2><p>Adjust the ingredients actually used. Include cooking fat once. Enter the weight of the whole cooked batch, including its water.</p><form id="recipe-form">${recipeDraft.map((x,i)=>`<div class="recipe-ingredient"><div class="tray-thumb">${foodVisual(x.food)}</div><label class="field">${esc(x.food.displayName||x.food.name)}${x.food.sourceUrl?`<a class="ingredient-source" href="${esc(x.food.sourceUrl)}" target="_blank" rel="noopener">Nutrient source ↗</a>`:''}<input data-recipe-grams="${i}" type="number" min="0.1" max="10000" step="0.1" required value="${x.grams}" aria-label="Ingredient grams: ${esc(x.food.name)}"></label><span>g</span><button type="button" class="text-button" data-remove-ingredient="${i}" aria-label="Remove ${esc(x.food.name)}">×</button></div>`).join('')}<div class="fat-shortcuts">${[['172336','+ Oil'],['173410','+ Butter'],['173412','+ Ghee']].map(([id,label])=>`<button type="button" class="secondary" data-recipe-fat="${id}">${label} · 5 g</button>`).join('')}</div><button type="button" class="text-button full" id="find-ingredient">+ Find another ingredient</button><label class="field">Recipe name<input id="recipe-name" required maxlength="180" value="${esc(recipeMeta.name||'')}" placeholder="My dal, chana, overnight oats…"></label><label class="field">Finished batch weight (g)<input id="recipe-weight" required type="number" min="1" max="20000" step="0.1" value="${esc(recipeMeta.weight||'')}"></label><p class="hint">Nutrition per 100 g of your finished recipe</p><div class="nutrition-preview" id="recipe-preview" aria-live="polite"></div><button class="primary" id="save-recipe">Save recipe & choose portion</button></form>`);
 const preview=()=>{remember();try{const nutrients=recipeNutrition(recipeDraft,Number(recipeMeta.weight));$('#recipe-preview').innerHTML=keys.map(k=>`<span><b>${nutrients[k]==null?'—':n(nutrients[k])}${k==='kcal'?'':' g'}</b>${names[k]}</span>`).join('');$('#save-recipe').disabled=false;}catch{$('#recipe-preview').textContent='Add ingredients and valid weights to calculate your recipe.';$('#save-recipe').disabled=true;}};
 document.querySelectorAll('[data-recipe-grams]').forEach(el=>el.oninput=()=>{recipeDraft[+el.dataset.recipeGrams].grams=el.valueAsNumber;preview();});
 $('#recipe-weight').oninput=preview;$('#recipe-name').oninput=remember;
 document.querySelectorAll('[data-remove-ingredient]').forEach(b=>b.onclick=()=>{remember();recipeDraft.splice(+b.dataset.removeIngredient,1);recipeBuilder();});
 document.querySelectorAll('[data-recipe-fat]').forEach(b=>b.onclick=()=>{remember();const food=allFoods().find(f=>f.id===b.dataset.recipeFat);const item=recipeDraft.find(x=>x.food.id===food.id);if(item)item.grams=(Number.isFinite(item.grams)?item.grams:0)+5;else recipeDraft.push({food:structuredClone(food),grams:5});recipeBuilder();});
 $('#find-ingredient').onclick=()=>{remember();close();navigate('food');notify('Tap a food, then choose “Add to recipe instead”.');};
 $('#recipe-form').onsubmit=e=>{e.preventDefault();remember();const weight=Number(recipeMeta.weight),food={id:'custom-recipe-'+crypto.randomUUID(),name:recipeMeta.name.trim(),source:'Your recipe · calculated',diet:recipeDraft.some(x=>x.food.diet==='other')?'other':recipeDraft.some(x=>x.food.diet==='dairy')?'dairy':'plant',basisGrams:100,batchGrams:weight,defaultGrams:100,image:recipeMeta.image,portions:[{label:'Full batch',grams:weight}],ingredients:structuredClone(recipeDraft),nutrients:recipeNutrition(recipeDraft,weight),note:'Calculated from your ingredient quantities and final cooked batch weight. Includes the fats listed in your recipe.'};if(!food.name)return;state.recipes.push(food);recipeDraft=[];recipeMeta={};persist();close();renderFood();portion(food);};preview();
}
function exportData(){const blob=new Blob([diaryCsv(state)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`gamna-diary-${localDate()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function foodGroup(f){const s=(f.name+' '+(f.category||'')).toLowerCase();if(f.ingredients)return 'Indian dishes';if(/butter|ghee|oil|fat and/.test(s))return 'Fats & oils';if(/milk|cheese|yogurt|curd|paneer|dairy/.test(s))return 'Dairy';if(/lentil|bean|chickpea|tofu|soya|soy |pea,|poultry|beef|pork|fish|egg|chicken|protein/.test(s))return 'Pulses & protein';if(/fruit|banana|apple|mango|berries|orange/.test(s))return 'Fruit';if(/vegetable|spinach|tomato|potato|onion|carrot|broccoli/.test(s))return 'Vegetables';if(/rice|oat|bread|wheat|cereal|grain|pasta|flour/.test(s))return 'Grains';return 'Other';}
function repeatMeal(){const groups=[];for(const [dt,d] of Object.entries(state.days).sort().reverse()){for(const meal of ['Breakfast','Lunch','Dinner','Snack']){const items=d.meals.filter(x=>x.meal===meal&&x.food);if(items.length)groups.push({dt,meal,items});}if(groups.length>=12)break;}modal(`<h2>A familiar favorite?</h2><p>Repeat a meal, then adjust its portions in your plate.</p>${groups.slice(0,12).map((g,i)=>`<button class="secondary full" style="margin:8px 0;text-align:left" data-repeat="${i}"><b>${esc(g.meal)} · ${g.dt}</b><br>${g.items.map(x=>esc(x.name)).join(', ')}</button>`).join('')||'<p>Your recent meals will appear here after you log them.</p>'}`);document.querySelectorAll('[data-repeat]').forEach(b=>b.onclick=()=>{tray=groups[+b.dataset.repeat].items.map(m=>({food:structuredClone(m.food),grams:m.grams}));close();navigate('food');});}
function renderWelcome(message=''){sessionReady=false;$('#content').replaceChildren();$('#modal-content').replaceChildren();close();$('.shell').hidden=true;$('#welcome').hidden=false;$('#welcome').innerHTML=`<nav class="welcome-nav"><a class="brand" href="#">gamna<span class="brand-dot">.</span></a><span class="live-badge">A little better, together.</span></nav><div class="welcome-main"><div class="welcome-copy"><span class="eyebrow">FOOD. MOVEMENT. YOUR MOMENTUM.</span><h1>Make room<br>for <em>you.</em></h1><p>A personal space for what you eat, how you move, and the small changes that add up. No perfect days required.</p><button class="primary" id="welcome-login" ${authSession?'':'disabled'}>${authSession?'Continue with Google':'Preparing secure sign-in…'}</button><p class="welcome-status" role="status">${esc(message)}</p><small>Your diary is private to your account.</small></div><div class="welcome-scene"><div class="landing-orbit"></div>${avatar(0)}<div class="floating-note"><small>A LITTLE MORE BALANCE</small><b>Food that fits your life.</b></div><div class="floating-note second"><small>YOUR OWN PACE</small><b>Progress, with perspective.</b></div></div></div><div class="welcome-features"><article><b>01 / Build your plate</b><p>Familiar dishes, precise portions, and recipes that reflect your cooking.</p></article><article><b>02 / Find your rhythm</b><p>Log movement and rest. Bring activity from a connected device or add it yourself.</p></article><article><b>03 / See the bigger picture</b><p>Explore your history and celebrate consistency, one day at a time.</p></article></div><footer>Gamna helps you record and understand your habits. You choose your goals.</footer>`;$('#welcome-login').onclick=()=>authSession.signIn().catch(e=>renderWelcome(e.code==='auth/popup-closed-by-user'?'Sign-in cancelled. Try again when you’re ready.':'Sign-in didn’t finish. Please allow the popup and try again.'));}
async function prepareAuth(){const config=window.SPROUT_CONFIG?.firebase;if(!config?.apiKey)return renderWelcome('Sign-in is temporarily unavailable. Please try later.');try{authSession=await createFirebaseSession(config,user=>{setTimeout(()=>openSession(user),0);});if(!cloudUser)renderWelcome();}catch{renderWelcome('Unable to connect to sign-in. Check your connection and reload.');}}
async function openSession(user){const epoch=++sessionEpoch;clearTimeout(syncTimer);sessionReady=false;profilePhoto=null;tray=[];state=blank();cloudUser=user;if(!user){renderWelcome();return;}renderWelcome('Opening your private diary…');try{const data=await api('/state');if(epoch!==sessionEpoch)return;legacyEligible=data.legacyEligible===true;let local;try{local=JSON.parse(localStorage.getItem(storageKey(user.uid)));}catch{}state=data.state?{...data.state,revision:data.revision,pending:false}:blank();state.profile.name=data.state?.profile.name||user.displayName?.split(' ')[0]||'You';if(local?.pending&&local.revision===data.revision)state=local;else if(local?.pending&&local.revision!==data.revision){notify('Another device has newer changes. Your unsaved copy is available in Profile.');}const profile=await api('/profile');if(epoch!==sessionEpoch)return;profilePhoto=profile.photo||null;sessionReady=true;$('#welcome').hidden=true;$('.shell').hidden=false;filter=state.profile.diet||'vegetarian';render();if(!state.profile.onboarded)onboarding();else if(state.pending)sync();}catch(e){if(epoch!==sessionEpoch)return;renderWelcome('Your diary could not load. Please retry; we won’t replace your saved entries.');$('#welcome-login').disabled=false;$('#welcome-login').textContent='Retry opening diary';$('#welcome-login').onclick=()=>openSession(user);}}
async function api(path,options={}){if(!window.SPROUT_CONFIG?.apiUrl)throw Error('Unable to connect. Please try again later.');if(!authSession||!cloudUser)throw Error('Please sign in to continue.');const epoch=sessionEpoch,uid=cloudUser.uid,bearer=await authSession.idToken(uid);if(epoch!==sessionEpoch||cloudUser?.uid!==uid)throw Error('Your session changed.');const res=await fetch(window.SPROUT_CONFIG.apiUrl+path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+bearer}});const data=await res.json();if(epoch!==sessionEpoch)throw Error('Your session changed.');if(!res.ok){const error=Error(data.error||'Could not save. Please try again.');error.acceptedRevision=data.acceptedRevision;error.status=res.status;throw error;}return data;}
async function sync(){if(!cloudUser||!sessionReady||syncing)return false;syncing=true;const epoch=sessionEpoch,eventId=state.eventId||crypto.randomUUID(),snapshot=structuredClone(Object.fromEntries(['version','days','customFoods','recipes','profile'].map(k=>[k,state[k]])));state.eventId=eventId;try{const data=await api('/sync',{method:'POST',body:JSON.stringify({eventId,baseRevision:state.revision,state:snapshot})});if(epoch!==sessionEpoch)return false;syncRetries=0;state.revision=data.revision;if(state.eventId===eventId)state.pending=false;saveLocal();updateStatus();return true;}catch(e){if(epoch!==sessionEpoch)return false;if(e.acceptedRevision){state.revision=e.acceptedRevision;saveLocal();if(syncRetries++<5){clearTimeout(syncTimer);syncTimer=setTimeout(sync,Math.min(60000,5000*2**syncRetries));}}notify(e.message);if(e.status===409)notify('Another device has newer changes. Open Profile to review your saved copy.');return false;}finally{syncing=false;if(epoch===sessionEpoch&&cloudUser&&state.eventId!==eventId&&state.pending){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}}
async function logout(){if(state.pending&&!await sync()){notify('You have unsaved changes. Export your diary before signing out.');return;}const key=cloudUser?storageKey(cloudUser.uid):null;await authSession.signOut();if(key)localStorage.removeItem(key);close();openSession(null);}
function onboarding(){modal(`<span class="eyebrow">WELCOME TO GAMNA</span><h2>Your space. Your pace.</h2><p>Let’s start with a name and food preference. You can review all daily targets in Goals.</p><form id="onboard"><label class="field">What should we call you?<input name="name" maxlength="60" required value="${esc(state.profile.name)}"></label><label class="field">Food preference<select name="diet"><option value="vegetarian">Vegetarian, including dairy</option><option value="plant">Plant-based</option><option value="all">All foods</option></select></label><p class="hint">Initial targets are editable examples, not calculated recommendations.</p><button class="primary">Make it mine</button></form>`);$('#onboard').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile.name=f.get('name').trim()||'You';state.profile.diet=f.get('diet');state.profile.onboarded=true;filter=state.profile.diet;persist();close();render();};}
function renderSettings(){$('#content').innerHTML=`<div class="settings-grid"><section class="card"><span class="eyebrow">DIRECTION, NOT PERFECTION</span><h2>Set your daily intentions.</h2><p>Choose targets that fit your life. These are your tracking preferences, not a personalized nutrition prescription.</p><form id="settings-form"><label class="field">Your focus<select name="goal"><option>Build strength & lose fat</option><option>Build strength</option><option>Gradual weight loss</option><option>Maintain & feel good</option></select></label><div class="form-grid">${Object.entries(state.profile.targets).map(([k,v])=>`<label class="field">${names[k]||({sleep:'Sleep',exercise:'Movement'}[k])} (${k==='kcal'?'kcal':k==='sleep'?'hours':k==='exercise'?'minutes':'g'})<input name="${k}" type="number" min="1" max="${k==='kcal'?10000:k==='sleep'?24:k==='exercise'?1440:1000}" step="${k==='sleep'?'.1':'1'}" required value="${v}"></label>`).join('')}</div><button class="primary">Save goals</button></form></section><section class="card"><span class="eyebrow">MAKE SPACE FOR CHANGE</span><h2>A target is a guide.</h2><p>You don’t need to hit every number every day. Look at patterns across weeks and adjust your goals when your circumstances change.</p><div class="insight"><span>✦</span><div><b>Keep the full picture in view.</b><p>Energy, strength, sleep and how you feel matter alongside the scale.</p></div></div><button id="go-progress" class="secondary">Explore your progress ↗</button></section></div>`;$('#settings-form [name=goal]').value=state.profile.goal;$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile.goal=f.get('goal');for(const k of Object.keys(state.profile.targets))state.profile.targets[k]=Number(f.get(k));persist();notify('Goals updated.');};$('#go-progress').onclick=()=>navigate('progress');}
function renderProfile(){$('#content').innerHTML=`<div class="profile-grid"><section class="profile-stage"><span class="eyebrow">YOUR EVERYDAY COMPANION</span><div id="profile-avatar">${avatar(pose,profilePhoto,state.profile.skin,state.profile.hair)}</div><p class="pose-label">${poses[pose]}</p><div class="profile-toolbar"><button class="secondary" id="next-pose">Another mood ↻</button><button class="secondary" id="remove-photo" ${profilePhoto?'':'disabled'}>Remove photo</button></div><p class="photo-hint">12 rendered 3D poses. Your profile photo is separate from your companion. Personalized avatar generation is being connected.</p>${profilePhoto?`<img class="profile-photo" src="${esc(profilePhoto)}" alt="Your private profile photo">`:""}<label class="field">Choose a profile photo<input class="photo-input" id="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="photo-hint">Your photo is resized and stripped of metadata in this browser, then saved privately. It is not sent to an AI image service.</p></section><section class="card"><span class="eyebrow">YOUR ACCOUNT</span><h2>Nice to see you, ${esc(state.profile.name)}.</h2><p>${esc(cloudUser.email)}</p><form id="profile-form"><label class="field">Display name<input name="name" value="${esc(state.profile.name)}" required maxlength="60"></label><label class="field">Food preference<select name="diet"><option value="vegetarian">Vegetarian, including dairy</option><option value="plant">Plant-based</option><option value="all">All foods</option></select></label><button class="primary">Save profile</button></form><hr><div class="toolbar"><button class="secondary" id="export-profile">Export diary CSV</button><button class="text-button" id="profile-logout">Log out</button><button class="text-button" id="refresh-diary">Load saved diary</button><button class="text-button" id="export-local">Export unsaved copy</button>${legacyEligible&&localStorage.getItem('sprout-v1')?'<button class="text-button" id="legacy-import">Review earlier diary</button>':''}</div><p class="hint">Your meals, measurements and photo belong to your signed-in account. CSV includes your diary entries, not your photo.</p></section></div>`;if($('#legacy-import'))$('#legacy-import').onclick=()=>{if(!confirm('Import your earlier diary from this browser? This replaces the current diary. Export it first if needed.'))return;try{const old=JSON.parse(localStorage.getItem('sprout-v1'));state={...old,revision:state.revision,pending:true};state.profile.onboarded=true;persist();render();}catch{notify('The earlier diary could not be read.');}};$('#profile-form [name=diet]').value=state.profile.diet;$('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const k of ['name','diet'])state.profile[k]=f.get(k).trim();if(!state.profile.name)state.profile.name='You';filter=state.profile.diet;persist();render();};$('#next-pose').onclick=()=>{pose=(pose+1)%12;renderProfile();};$('#photo').onchange=uploadPhoto;$('#remove-photo').onclick=async()=>{try{await api('/profile',{method:'POST',body:JSON.stringify({photo:null})});profilePhoto=null;renderProfile();}catch(e){notify(e.message);}};$('#export-profile').onclick=exportData;$('#profile-logout').onclick=logout;$('#refresh-diary').onclick=()=>{if(confirm('Load your saved diary? Export any unsaved entries first.'))openSession(cloudUser);};$('#export-local').onclick=()=>{let saved;try{saved=JSON.parse(localStorage.getItem(storageKey(cloudUser.uid)));}catch{}if(!saved)return notify('There is no unsaved copy on this device.');const current=state;state=saved;exportData();state=current;};}
async function uploadPhoto(e){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)return notify('Choose a JPG, PNG or WebP smaller than 10 MB.');const epoch=sessionEpoch;try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=canvas.height=240;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.fillStyle='#eee';ctx.fillRect(0,0,240,240);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,240,240);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.8);if(epoch!==sessionEpoch)return;await api('/profile',{method:'POST',body:JSON.stringify({photo})});if(epoch!==sessionEpoch)return;profilePhoto=photo;renderProfile();notify('Your companion has a new look.');}catch{notify('Photo could not be saved. Try a different image.');}}
function renderProgress(){const rows=periodRows(state.days,date,progressRange),metric=progressMetric,valid=rows.filter(r=>r[metric]!=null),unit=metric==='weight'?'kg':metric==='sleep'?'h':metric==='minutes'?'min':metric==='kcal'?'kcal':'g',label=({weight:'Weight',sleep:'Sleep',minutes:'Movement',...names})[metric];const average=valid.length?valid.reduce((s,r)=>s+r[metric],0)/valid.length:null,half=Math.floor(rows.length/2),avg=a=>{const v=a.filter(r=>r[metric]!=null);return v.length?v.reduce((s,r)=>s+r[metric],0)/v.length:null;},before=avg(rows.slice(0,half)),after=avg(rows.slice(half)),logged=rows.filter(r=>state.days[r.date]?.meals.length||state.days[r.date]?.exercise.length||r.weight!=null||r.sleep!=null).length;let chart='<div class="meal-empty"><h3>Your next chapter starts here.</h3><p>Log two days of this measurement to reveal your trend.</p></div>';if(valid.length>=2){const values=valid.map(r=>r[metric]),lo=Math.min(...values),span=Math.max(1,Math.max(...values)-lo),x=i=>50+i/(rows.length-1)*620,y=v=>210-(v-lo)/span*165;let paths='',segment=[];for(let i=0;i<rows.length;i++){if(rows[i][metric]==null){if(segment.length)paths+=`<polyline points="${segment.join(' ')}"/>`;segment=[];}else segment.push(`${x(i)},${y(rows[i][metric])}`);}if(segment.length)paths+=`<polyline points="${segment.join(' ')}"/>`;chart=`<svg class="progress-chart" viewBox="0 0 720 260" role="img" aria-label="${label} trend across ${progressRange} days; gaps are unlogged days"><defs><linearGradient id="chart-stroke"><stop stop-color="#7b9856"/><stop offset="1" stop-color="#b2d86f"/></linearGradient></defs><path d="M50 45H670 M50 127H670 M50 210H670" stroke="#e3e8dd"/><text x="5" y="48" font-size="12" fill="#607164">${n(lo+span)}</text><text x="5" y="213" font-size="12" fill="#607164">${n(lo)}</text><g stroke="url(#chart-stroke)" stroke-width="4" fill="none" stroke-linejoin="round">${paths}</g>${rows.map((r,i)=>r[metric]==null?'':`<circle class="chart-point" cx="${x(i)}" cy="${y(r[metric])}" r="5" fill="#6b9051" tabindex="0"><title>${r.date}: ${n(r[metric])} ${unit}</title></circle>`).join('')}<text x="50" y="247" font-size="12" fill="#607164">${rows[0].date}</text><text x="590" y="247" font-size="12" fill="#607164">${date}</text></svg>`;}$('#content').innerHTML=`<section class="progress-hero"><div><span class="eyebrow">PROGRESS IS PERSONAL</span><h2>Look at you, showing up.</h2><p>${logged?`${logged} days with a check-in in this ${progressRange}-day chapter.`:'Each check-in adds another piece to your story.'}</p><span class="pill">${state.profile.goal?esc(state.profile.goal):'Your own pace'}</span></div>${avatar(0,profilePhoto,state.profile.skin,state.profile.hair)}</section><div class="section-heading"><h2>Your trends</h2><select id="progress-range" aria-label="Time range">${[7,28,90].map(v=>`<option value="${v}" ${v===progressRange?'selected':''}>${v} days</option>`).join('')}</select></div><div class="metric-selector">${Object.entries({weight:'Weight',kcal:'Calories',protein:'Protein',fat:'Fat',carbs:'Carbs',fiber:'Fiber',sleep:'Sleep',minutes:'Movement'}).map(([k,v])=>`<button data-metric="${k}" class="${k===metric?'selected':''}">${v}</button>`).join('')}</div><div class="progress-stats"><section class="card"><small>Period average</small><strong>${average==null?'—':n(average)} <small>${unit}</small></strong></section><section class="card"><small>Second half vs first half</small><strong>${before==null||after==null?'—':(after-before>0?'+':'')+n(after-before)} <small>${unit}</small></strong></section><section class="card"><small>Days with ${label.toLowerCase()}</small><strong>${valid.length}<small> / ${progressRange}</small></strong></section></div><section class="card"><h3>${label}, over time</h3>${chart}<p class="chart-description">Missing days stay blank. Partial nutrition totals are excluded. Hover or focus a point for its value. Comparisons describe your logged data, not cause and effect.</p></section><section class="card" style="margin-top:22px"><h3>Small steps, collected.</h3><div class="consistency">${rows.map(r=>`<span title="${r.date}" aria-label="${r.date}: ${state.days[r.date]?'has entries':'no entries'}" class="${state.days[r.date]?'logged':''}"></span>`).join('')}</div></section><section class="card" style="margin-top:22px"><div class="card-head"><h3>Foods you come back to</h3><button id="export-progress" class="text-button">Export CSV</button></div><p class="hint">Average nutrients per logged serving. Portion sizes may differ.</p><div class="table-wrap"><table class="compare-table"><thead><tr><th>Food</th><th>Times logged</th><th>Average grams</th><th>Calories</th><th>Protein</th></tr></thead><tbody>${foodComparison(rows)||'<tr><td colspan="5">Log meals to explore your patterns here.</td></tr>'}</tbody></table></div></section>`;$('#export-progress').onclick=exportData;$('#progress-range').onchange=e=>{progressRange=+e.target.value;renderProgress();};document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{progressMetric=b.dataset.metric;renderProgress();});}
function foodComparison(rows){const map=new Map();for(const r of rows)for(const m of state.days[r.date]?.meals||[]){const key=m.foodId||m.name;if(!map.has(key))map.set(key,[]);map.get(key).push(m);}return [...map.values()].sort((a,b)=>b.length-a.length).slice(0,10).map(ms=>{const avg=k=>ms.some(m=>m.nutrients[k]==null)?'—':n(ms.reduce((s,m)=>s+m.nutrients[k],0)/ms.length);return `<tr><td>${esc(ms[0].name)}</td><td>${ms.length}</td><td>${n(ms.reduce((s,m)=>s+m.grams,0)/ms.length)}</td><td>${avg('kcal')}</td><td>${avg('protein')} g</td></tr>`;}).join('');}
function renderTraining(){const providers=[['◉','Resistance bands','HASfit','Follow-along resistance-band sessions.','https://hasfit.com/workouts/home/strength-weight-training/full-body-resistance-band-workout/'],['↗','Strength & cardio','Fitness Blender','Filter sessions by equipment, duration and training style.','https://www.fitnessblender.com/videos'],['☾','Yoga & mobility','Yoga With Adriene','Explore guided yoga sessions and movement practices.','https://yogawithadriene.com/free-yoga-videos/']];const recent=Object.entries(state.days).sort().reverse().flatMap(([dt,d])=>d.exercise.map(e=>({...e,date:dt}))).slice(0,10);$('#content').innerHTML=`<section class="activity-hero"><div><span class="eyebrow">YOUR MOVEMENT JOURNAL</span><h2>Find what brings you back.</h2><p>Keep your favorite coaches. Collect the movement that fits your day.</p></div><button class="primary" id="record-workout">+ Log activity</button></section><div class="section-heading"><h2>Explore a style</h2><span class="muted">Independent providers</span></div><div class="provider-grid">${providers.map(([icon,type,name,copy,url])=>`<section class="card"><span class="provider-icon">${icon}</span><p class="eyebrow">${type}</p><h3>${name}</h3><p>${copy}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Explore sessions ↗</a></section>`).join('')}</div><p class="hint">Choose sessions suited to your experience and equipment. These links are a discovery library, not a prescribed training plan or endorsement.</p><section class="card activity-history"><h2>Your repeatable wins</h2><p>Bring back a session you enjoyed. Adjust its time before saving.</p>${recent.map((e,i)=>`<div class="meal-row"><div class="meal-info"><b>${esc(e.name)}</b><small>${e.date} · ${e.minutes} minutes</small></div><button class="secondary" data-repeat-activity="${i}">Do again</button></div>`).join('')||'<p class="muted">Your logged sessions will appear here.</p>'}</section><section class="card connection-card"><span class="eyebrow">LESS TYPING, MORE LIVING</span><h2>Connected activity</h2><p>Add activity, weight or sleep manually, or send measurements from an automation such as iPhone Shortcuts. Incoming entries wait for your review.</p><div class="toolbar"><button class="secondary" id="review-imports">Review incoming entries</button><button class="text-button" id="setup-connection">Set up a connection</button></div><div id="connection-panel"></div></section>`;$('#record-workout').onclick=()=>checkin('exercise');document.querySelectorAll('[data-repeat-activity]').forEach(b=>b.onclick=()=>{checkin('exercise');$('#check-form [name=value]').value=recent[+b.dataset.repeatActivity].minutes;const select=$('#check-form [name=activity]');if([...select.options].some(o=>o.value===recent[+b.dataset.repeatActivity].name))select.value=recent[+b.dataset.repeatActivity].name;});$('#review-imports').onclick=reviewImports;$('#setup-connection').onclick=connectionSetup;}
async function connectionSetup(){const endpoint=window.SPROUT_CONFIG.apiUrl+'/activity';$('#connection-panel').innerHTML=`<details open><summary>Connect an automation</summary><p>Create a private upload key. It expires after 14 days and can only send measurements—it cannot read your diary.</p><button class="secondary" id="create-key">Create / replace key</button> <button class="text-button" id="revoke-key">Disconnect</button><div id="key-result"></div><ol><li>On iPhone, create a Shortcut and add <b>Find Health Samples</b>. Choose one measurement and its date; allow access only to the measurements you want to share.</li><li>Format its date as <b>yyyy-MM-dd</b>. Convert weight to kilograms, sleep to hours, or activity to minutes. For sleep, avoid counting overlapping stages twice.</li><li>Add <b>Get Contents of URL</b>, set the URL below, method <b>POST</b>, and request body <b>JSON</b>.</li><li>Add an <b>Authorization</b> header: <b>Bearer YOUR_KEY</b>. Keep the key private.</li><li>Use a stable <b>sourceId</b> for each sample (such as its sample identifier). Retrying the same sample will not duplicate it.</li><li>Run the Shortcut, then select <b>Review incoming entries</b> here.</li></ol><p>URL</p><pre>${esc(endpoint)}</pre><p>Example body for one activity. Replace these fields with your Shortcut variables.</p><pre>${esc(JSON.stringify({sourceId:'workout-unique-id',date:localDate(),name:'Walking',minutes:25},null,2))}</pre><p class="hint">For weight use <code>weight</code> in kg; for sleep use <code>sleep</code> in hours. Other automation tools can send the same request. This does not connect automatically to any health platform.</p><a href="https://support.apple.com/guide/shortcuts/request-your-first-api-apd58d46713f/ios" target="_blank" rel="noopener">Apple’s guide to sending requests ↗</a></details>`;$('#create-key').onclick=async()=>{try{const data=await api('/connections',{method:'POST',body:JSON.stringify({action:'create'})});$('#key-result').innerHTML=`<p class="notice">Copy this key now; it won’t be shown again. Creating another key disconnects the old one.</p><pre>${esc(data.token)}</pre><p>Expires ${new Date(data.expires*1000).toLocaleDateString()}</p>`;}catch(e){notify(e.message);}};$('#revoke-key').onclick=async()=>{try{await api('/connections',{method:'POST',body:JSON.stringify({action:'revoke'})});$('#key-result').textContent='Connection disconnected.';}catch(e){notify(e.message);}};}
async function reviewImports(){try{const {items}=await api('/imports');modal(`<h2>Ready for your review</h2><p>Weight and sleep replace the selected day’s existing value. Activities are added once.</p>${items.map((x,i)=>`<div class="card" style="margin:12px 0"><b>${esc(x.date)} · ${esc(x.name||'Check-in')}</b><p>${[x.minutes!=null?x.minutes+' minutes':null,x.weight!=null?x.weight+' kg':null,x.sleep!=null?x.sleep+' hours sleep':null].filter(Boolean).join(' · ')}</p><button class="primary" data-accept="${i}">Accept</button> <button class="text-button" data-dismiss="${i}">Dismiss</button></div>`).join('')||'<p>No incoming entries. You’re all caught up.</p>'}`);document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{b.disabled=true;const item=items[+b.dataset.accept],d=state.days[item.date]||{meals:[],exercise:[],weight:null,sleep:null};d.importedIds=d.importedIds||[];if(!d.importedIds.includes(item.id)){if(item.weight!=null)d.weight=item.weight;if(item.sleep!=null)d.sleep=item.sleep;if(item.minutes!=null)d.exercise.push({id:item.id,name:item.name,minutes:item.minutes,source:'connected'});d.importedIds.push(item.id);state.days[item.date]=d;persist();}clearTimeout(syncTimer);if(!await sync()){b.disabled=false;return notify('Save is pending. Try again before accepting more entries.');}await api('/imports/ack',{method:'POST',body:JSON.stringify({ids:[item.id]})});close();render();notify('Entry added to your diary.');});document.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=async()=>{try{await api('/imports/ack',{method:'POST',body:JSON.stringify({ids:[items[+b.dataset.dismiss].id]})});close();reviewImports();}catch(e){notify(e.message);}});}catch(e){notify(e.message);}}

function attachDepth(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('.mission-scene,.combo-card,.visual-food-card').forEach(el=>{el.onpointermove=e=>{if(e.pointerType==='touch')return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.setProperty('--rx',(-y*5)+'deg');el.style.setProperty('--ry',(x*7)+'deg');};el.onpointerleave=()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg');};});}


