function lookupBarcode(){modal(`<h2>Find your exact product.</h2><p>Enter the barcode on the pack to look up its photo and nutrition in Open Food Facts. Always compare the result with your label.</p><form id="barcode-form"><label class="field">Barcode<input name="code" inputmode="numeric" pattern="[0-9]{8,14}" minlength="8" maxlength="14" required placeholder="8–14 digits"></label><button class="primary">Look up product</button></form><p id="barcode-status" role="status"></p><p class="hint">Community data from <a href="https://world.openfoodfacts.org" target="_blank" rel="noopener">Open Food Facts</a>, licensed under ODbL. Product images: CC BY-SA. A lookup sends the barcode to this provider.</p>`);$('#barcode-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#barcode-status').textContent='Finding your product…';try{const {food}=await api('/foods/barcode/'+encodeURIComponent(new FormData(e.target).get('code')));if(!state.customFoods.some(f=>f.id===food.id)){state.customFoods.push(food);persist();}close();portion(food);}catch(error){if($('#barcode-status'))$('#barcode-status').textContent=error.message;}finally{button.disabled=false;}};}
